  rate: { l: 'Expected divorce filings per 1,000 married', cl: 'Divorce filings per 1,000 married adults', grp: 'Filings', g: 'C', cg: 'A', ramp: 'ember', z: z => z.exp_div_per_1k_married, c: c => c.rates.div_per_1k_married, f: v => N(v, 1), note: 'A ZIP rate is the allocation over the ZIP\'s married adults, so it moves with the modeled hazard, not with local court records.' },
