  po: { l: 'Expected protective order applications a year', cl: 'Protective order applications, trailing 12 months', grp: 'Filings', g: 'C', cg: 'A', ramp: 'ember', z: z => z.alloc.po, c: c => c.filings.ttm.po, f: v => N(v, 0), log: true, note: 'Family Code Title 4 protective orders.' },
  me: { l: 'Expected modifications and enforcements a year', cl: 'Modifications and enforcements, trailing 12 months', grp: 'Filings', g: 'C', cg: 'A', ramp: 'ember', z: z => (z.alloc.mod || 0) + (z.alloc.enf || 0), c: c => (c.filings.ttm.mod || 0) + (c.filings.ttm.enf || 0), f: v => N(v, 0), log: true, note: 'Existing orders relitigated: the least cyclical family law work (module 05).' },
