  const rx = (a, b) => isN(a) && isN(b) && b > 0 ? a / b : null; const cl19 = rx(S.w13, S.w13_19), clY = rx(S.w13, S.w13y); const odd = [cl19, clY].some(v => isN(v) && (v < 0.5 || v > 2));
